// stores/cart.ts
import { defineStore } from 'pinia'

export interface CartItem {
  id: string
  name: string
  price: number
  quantity: number
}

interface CartState {
  items: CartItem[]
}

export const useCartStore = defineStore('cart', {
  state: (): CartState => ({
    items: [],
  }),

  getters: {
    total: (state): number =>
      state.items.reduce((sum, item) => sum + item.price * item.quantity, 0),

    itemCount: (state): number =>
      state.items.reduce((sum, item) => sum + item.quantity, 0),
  },

  actions: {
    addItem(item: Omit<CartItem, 'quantity'>, quantity = 1) {
      const existing = this.items.find((i) => i.id === item.id)
      if (existing) {
        existing.quantity += quantity
      } else {
        this.items.push({ ...item, quantity })
      }
    },

    removeItem(id: string) {
      const index = this.items.findIndex((i) => i.id === id)
      if (index !== -1) {
        this.items.splice(index, 1)
      }
    },

    clearCart() {
      this.items = []
    },
  },
})
```

Uses the Options-style `defineStore` API (state/getters/actions) since it maps cleanly to a typed cart model; `addItem` merges quantities for duplicate `id`s, and `removeItem` deletes the item entirely rather than decrementing.
